function ibIcon(name, options = {}) {
  const {
    size = 16,
    className = '',
    color = 'currentColor',
    title = '',
    ariaHidden = !title,
  } = options;
  const inner = POLLEN_ICONS[name];
  if (!inner) {
    console.warn('Unknown icon:', name);
    return '';
  }
  const classes = ['ib-icon', className].filter(Boolean).join(' ');
  const label = title ? ` aria-label="${title}" role="img"` : (ariaHidden ? ' aria-hidden="true"' : '');
  const style = color && color !== 'currentColor' ? ` style="color:${color}"` : '';
  return `<svg class="${classes}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"${style}${label}>${inner}</svg>`;
}

function initIcons(root = document) {
  root.querySelectorAll('[data-icon]').forEach(el => {
    const name = el.getAttribute('data-icon');
    const size = parseInt(el.getAttribute('data-size') || '16', 10);
    const color = el.getAttribute('data-color') || 'currentColor';
    const className = el.getAttribute('data-icon-class') || '';
    const title = el.getAttribute('data-icon-title') || '';
    el.outerHTML = ibIcon(name, { size, color, className, title });
  });
}

if (typeof module !== 'undefined') module.exports = { POLLEN_ICONS, ibIcon, initIcons };
